      padding: 0.55rem 0.8rem;
      border-radius: 999px;
      background: rgba(9, 17, 31, 0.72);
      color: #fff;
      font-size: 0.9rem;
    }

    .card-body,
    .sidebar-card {
      padding: 1.5rem;
    }

    .eyebrow {
      margin: 0 0 0.7rem;
      color: var(--accent);
      font-size: 0.9rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
    }

    h1,
    h2 {
      margin: 0;
      letter-spacing: -0.04em;
      line-height: 1.05;
    }

    h1 {
      font-size: clamp(2rem, 5vw, 3.5rem);
      max-width: 12ch;
    }

    h2 {
      font-size: clamp(1.5rem, 3vw, 2rem);
    }

    .lede,
    .dialog-copy,
    .detail-list,
    .status {
      color: var(--muted);
    }

    .lede {
      margin: 1rem 0 0;
      max-width: 58ch;
      line-height: 1.6;
    }

    .actions {
      display: flex;
      flex-wrap: wrap;
      gap: 0.85rem;
      margin-top: 1.5rem;
    }

    .button {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      min-height: 2.9rem;
      padding: 0.9rem 1.15rem;
      border-radius: 999px;
      font-weight: 700;
      transition: transform 0.18s ease, background 0.18s ease, color 0.18s ease;
    }

    .button:hover {
      transform: translateY(-1px);
    }

    .button-secondary {
      border: 1px solid var(--line);
      background: transparent;
      color: var(--text);
    }

    .button-primary {
      background: var(--accent);
      color: #fff;
    }

    .button-primary:hover {
      background: var(--accent-strong);
    }

    .button-danger {
      background: var(--danger);
      color: #fff;
    }

    .button-danger:hover {
      background: var(--danger-strong);
    }

    .detail-list {
      margin: 1rem 0 0;
      padding: 0;
      list-style: none;
      display: grid;
      gap: 0.8rem;
      line-height: 1.45;
    }

    .detail-list strong {
      color: var(--text);
    }

    .status {
      margin-top: 1rem;
      min-height: 1.5rem;
      font-size: 0.95rem;
      line-height: 1.5;
    }

    .empty-state {
      display: grid;
      place-items: center;
      text-align: center;
      min-height: 380px;
      padding: 2rem;
    }

    .empty-state p {
      margin: 0.9rem 0 0;
      color: var(--muted);
      max-width: 36ch;
      line-height: 1.6;
    }

    dialog {
      width: min(92vw, 30rem);
      padding: 0;
      color: var(--text);
    }

    dialog::backdrop {
      background: rgba(7, 11, 22, 0.58);
      backdrop-filter: blur(8px);
