        --line: CanvasText;
        --accent: Highlight;
        --accent-strong: Highlight;
        --danger: Mark;
        --danger-strong: Mark;
      }

      .brand-badge,
      .button-primary,
      .button-danger {
        forced-color-adjust: none;
        background: ButtonFace;
        color: ButtonText;
        border: 1px solid ButtonText;
      }

      .meta-chip,
      .card,
      .sidebar-card,
      dialog {
        box-shadow: none;
      }
    }
  </style>
</head>
<body>
  <div id="app"></div>
  <script>
    const state = {
      isDeleted: false,
      statusMessage: ""
    };

    function Header() {
      return `
        <header class="shell">
          <a class="skip-link" href="#maincontent">Skip to main content</a>
          <div class="topbar">
            <div class="brand" aria-label="FrameFlow">
              <span class="brand-badge" aria-hidden="true">F</span>
              <span>FrameFlow</span>
            </div>
            <div class="meta-chip" aria-label="Collection details">
              <span aria-hidden="true">Library</span>
              <span>1 selected preview</span>
            </div>
          </div>
        </header>
      `;
    }

    function ImageDetails() {
      return `
        <aside class="sidebar-card" aria-labelledby="details-heading">
          <p class="eyebrow">Metadata</p>
          <h2 id="details-heading">Ready to publish</h2>
          <ul class="detail-list">
            <li><strong>Name:</strong> Coastal Horizon</li>
            <li><strong>Resolution:</strong> 3840 × 2400</li>
            <li><strong>Added:</strong> May 2, 2026</li>
            <li><strong>Visibility:</strong> Private library asset</li>
          </ul>
          <p class="status" aria-live="polite">${state.statusMessage}</p>
        </aside>
      `;
    }

    function ImagePreview() {
      if (state.isDeleted) {
        return `
          <section class="card empty-state" aria-labelledby="empty-heading">
            <div>
              <p class="eyebrow">Library updated</p>
              <h2 id="empty-heading">Image removed</h2>
              <p>The preview has been deleted from your library and is no longer available in this collection.</p>
            </div>
          </section>
        `;
      }

      return `
        <section class="card" aria-labelledby="preview-heading">
          <figure class="media-frame" aria-label="Photo preview of a shoreline at sunset">
            <div class="media-label">Preview image</div>
          </figure>
          <div class="card-body">
            <p class="eyebrow">Image preview</p>
            <h1 id="preview-heading">Coastal Horizon</h1>
            <p class="lede">
              Review the final crop, metadata, and publishing status before sharing this image with your team.
              You can remove it from your library at any time.
            </p>
            <div class="actions">
              <button type="button" class="button button-secondary">Download</button>
              <button type="button" class="button button-danger trigger" id="open-delete-dialog">
                Delete image
              </button>
            </div>
          </div>
        </section>
      `;
    }

    function DeleteDialog() {
      return `
        <dialog id="delete-dialog" aria-labelledby="delete-dialog-title" aria-describedby="delete-dialog-description">
          <div class="dialog-panel">
            <p class="eyebrow">Confirm deletion</p>
            <h2 id="delete-dialog-title">Delete this image from your library?</h2>
            <p class="dialog-copy" id="delete-dialog-description">
              This action permanently removes <strong>Coastal Horizon</strong> from your library. Any links or collections
              using this image will no longer be able to preview it.
            </p>
            <div class="dialog-actions">
              <button type="button" class="button button-secondary" data-action="cancel">Cancel</button>
              <button type="button" class="button button-danger" data-action="confirm">Delete image</button>
            </div>
          </div>
        </dialog>
      `;
    }

    function App() {
      return `
        ${Header()}
        <main class="shell" id="maincontent" tabindex="-1">
          <section class="hero" aria-label="Image preview layout">
            ${ImagePreview()}
            ${ImageDetails()}
          </section>
        </main>
        ${DeleteDialog()}
      `;
    }

    function bindEvents() {
      const trigger = document.getElementById("open-delete-dialog");
      const dialog = document.getElementById("delete-dialog");
      const cancelButton = dialog.querySelector('[data-action="cancel"]');
      const confirmButton = dialog.querySelector('[data-action="confirm"]');

      if (trigger) {
        trigger.addEventListener("click", () => dialog.showModal());
      }

      cancelButton.addEventListener("click", () => dialog.close("cancel"));

      confirmButton.addEventListener("click", () => {
        state.isDeleted = true;
        state.statusMessage = "Image deleted from your library.";
        dialog.close("delete");
        render();
      });

      dialog.addEventListener("click", (event) => {
        const bounds = dialog.getBoundingClientRect();
        const clickedOutside =
          event.clientX < bounds.left ||
          event.clientX > bounds.right ||
          event.clientY < bounds.top ||
          event.clientY > bounds.bottom;

        if (clickedOutside) {
          dialog.close("cancel");
        }
      });
    }

    function render() {
      const appRoot = document.getElementById("app");
      appRoot.innerHTML = App();
      bindEvents();
    }

    render();
  </script>
</body>
</html>
