               <span aria-hidden="true">Library</span>
               <span>1 selected preview</span>
             </div>
           </div>
         </header>
       `;
     }

     function ImageDetails() {
       return `
         <aside class="sidebar-card" aria-labelledby="details-heading">
           <p class="eyebrow">Metadata</p>
           <h2 id="details-heading">Ready to publish</h2>
           <ul class="detail-list">
