           </ul>
           <p class="status" aria-live="polite">${state.statusMessage}</p>
         </aside>
       `;
     }

     function ImagePreview() {
       if (state.isDeleted) {
         return `
           <section class="card empty-state" aria-labelledby="empty-heading">
             <div>
               <p class="eyebrow">Library updated</p>
               <h2 id="empty-heading">Image removed</h2>
               <p>The preview has been deleted from your library and is no longer available in this collection.</p>
             </div>
           </section>
         `;
       }

       return `
         <section class="card" aria-labelledby="preview-heading">
           <figure class="media-frame" aria-label="Photo preview of a shoreline at sunset">
             <div class="media-label">Preview image</div>
           </figure>
           <div class="card-body">
             <p class="eyebrow">Image preview</p>
             <h1 id="preview-heading">Coastal Horizon</h1>
             <p class="lede">
