               You can remove it from your library at any time.
             </p>
             <div class="actions">
               <button type="button" class="button button-secondary">Download</button>
               <button type="button" class="button button-danger trigger" id="open-delete-dialog">
                 Delete image
               </button>
             </div>
           </div>
         </section>
       `;
     }

     function DeleteDialog() {
       return `
         <dialog id="delete-dialog" aria-labelledby="delete-dialog-title" aria-describedby="delete-dialog-description">
           <div class="dialog-panel">
             <p class="eyebrow">Confirm deletion</p>
             <h2 id="delete-dialog-title">Delete this image from your library?</h2>
             <p class="dialog-copy" id="delete-dialog-description">
