               <button type="button" class="button button-secondary" data-action="cancel">Cancel</button>
               <button type="button" class="button button-danger" data-action="confirm">Delete image</button>
             </div>
           </div>
         </dialog>
       `;
     }

     function App() {
       return `
         ${Header()}
         <main class="shell" id="maincontent" tabindex="-1">
           <section class="hero" aria-label="Image preview layout">
             ${ImagePreview()}
             ${ImageDetails()}
           </section>
         </main>
         ${DeleteDialog()}
       `;
     }

     function bindEvents() {
       const trigger = document.getElementById("open-delete-dialog");
       const dialog = document.getElementById("delete-dialog");
       const cancelButton = dialog.querySelector('[data-action="cancel"]');
       const confirmButton = dialog.querySelector('[data-action="confirm"]');

       if (trigger) {
