      const trigger = document.getElementById("open-delete-dialog");
      const dialog = document.getElementById("delete-dialog");
      const cancelButton = dialog.querySelector('[data-action="cancel"]');
      const confirmButton = dialog.querySelector('[data-action="confirm"]');

      if (trigger) {
        trigger.addEventListener("click", () => dialog.showModal());
      }

      cancelButton.addEventListener("click", () => dialog.close("cancel"));

      confirmButton.addEventListener("click", () => {
        state.isDeleted = true;
        state.statusMessage = "Image deleted from your library.";
        dialog.close("delete");
        render();
      });

      dialog.addEventListener("click", (event) => {
        const bounds = dialog.getBoundingClientRect();
        const clickedOutside =
          event.clientX < bounds.left ||
          event.clientX > bounds.right ||
          event.clientY < bounds.top ||
          event.clientY > bounds.bottom;

        if (clickedOutside) {
          dialog.close("cancel");
        }
      });
    }

    function render() {
      const appRoot = document.getElementById("app");
      appRoot.innerHTML = App();
      bindEvents();

      if (state.isDeleted) {
        const heading = document.getElementById("empty-heading");
        if (heading) {
          heading.focus();
        }
      }
    }

